INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷103·隐帝本纪·十二月北征与任命", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b7c52ba6cde22f73d5e0bc2ffea0ec77f628d107/content/books/zizhi-tongjian/vol-289/year-0950/part-11/sources/library/jiuwudaishi-103-december-expedition/source.txt", "note": "《旧五代史》卷103·隐帝本纪·十二月北征与任命，段落 jiu-wudaishi-205deb4a7860-p002502；已核上下文及传主，纸本及异文待核。", "id": "58b01b09-5220-5d32-93ca-6bbb7fcb25bb"}, {"title": "辽史·卷5·世宗本纪·天禄四年十月南伐", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b7c52ba6cde22f73d5e0bc2ffea0ec77f628d107/content/books/zizhi-tongjian/vol-289/year-0950/part-11/sources/library/liaoshi-005-neiqiu-invasion/source.txt", "note": "《辽史》卷5·世宗本纪·天禄四年十月南伐，段落 liaoshi-7cd182a20e67-p000611；已核上下文及传主，纸本及异文待核。", "id": "744361cb-5128-56a2-9b3f-ca03995dfbf0"}, {"title": "新五代史·卷66·楚世家·彭师暠作战建议", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b7c52ba6cde22f73d5e0bc2ffea0ec77f628d107/content/books/zizhi-tongjian/vol-289/year-0950/part-11/sources/library/xinwudaishi-066-peng-plan/source.txt", "note": "《新五代史》卷66·楚世家·彭师暠作战建议，段落 xin-wudaishi-b08f244b9241-p003330；已核上下文及传主，纸本及异文待核。", "id": "34ae526f-1c32-5c88-a412-f5ce023299fe"}, {"title": "资治通鉴·卷289·乾祐三年·临朝与楚军防御", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/92e50fd2e637679a259045dd4484586b57ae2038/content/books/zizhi-tongjian/vol-289/year-0950/part-10/sources/library/tongjian-289-950-regency-chu-defense/source.txt", "note": "《资治通鉴》卷289·乾祐三年·临朝与楚军防御，段落 zizhi-tongjian-a63549944a71-p003437；已核上下文及传主，纸本及异文待核。", "id": "3162961e-b83b-5558-8393-bf0badc8d5e4"}, {"title": "旧五代史·卷103·隐帝本纪·迎嗣与临朝", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/92e50fd2e637679a259045dd4484586b57ae2038/content/books/zizhi-tongjian/vol-289/year-0950/part-10/sources/library/jiuwudaishi-103-succession-regency/source.txt", "note": "《旧五代史》卷103·隐帝本纪·迎嗣与临朝，段落 jiu-wudaishi-205deb4a7860-p002501；已核上下文及传主，纸本及异文待核。", "id": "50558b51-7a36-5d54-a520-55c401d3f84b"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "李氏（刘知远妻）", "aliases": ["李氏（後漢高祖后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，刘知远的妻子。947年二月劝丈夫停止征民财劳军，改用宫中积蓄，建议获采纳。《旧五代史》称高祖皇后李氏，此时《通鉴》称夫人李氏，正式册后另在后续时间录入。名字与生卒年暂未录入。", "biography": null, "status": "draft", "id": "10b635fe-af1e-534c-891a-5b82288872e1"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "窦贞固", "aliases": ["竇貞固"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：窦贞固，原节度推官、获任者。", "biography": null, "status": "draft", "id": "628caf07-3ba2-5bc4-8630-598667f5bdd0"}, {"name": "苏禹珪", "aliases": ["蘇禹珪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "密州人，任河东观察判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "b8c912f3-4f5e-5fbc-9714-9caaf03ed98c"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "王殷（后汉后周将）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瀛州籍将领。950年以侍卫步军都指挥使身份奉命驻澶州防备契丹，后来参与后周建国。《旧五代史》记他自称出生在魏州开元寺，籍贯与出生地分开。与晚唐后梁同名王殷分开建档，生卒年本批未录。", "biography": null, "status": "draft", "id": "4b85115a-7337-546f-af4c-9f6bd20f13c6"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}, {"name": "彭师暠", "aliases": ["彭師暠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "彭士愁的儿子。940年受父亲派遣，率诸酋长向楚交出溪、锦、奖三州官印，请求归降。生卒年未载。", "biography": null, "status": "draft", "id": "9a01204b-6429-53ed-8ca1-76b3143bd4d8"}, {"name": "马希广", "aliases": ["馬希廣", "德丕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马希广，武安节度副使，临时领府者。", "biography": null, "status": "draft", "id": "eb8e4d76-8384-56ed-a225-77675cfd8927"}, {"name": "朱进忠", "aliases": ["硃进忠", "朱進忠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希萼的指挥使。950年率兵三千攻益阳，随后建议马希萼亲自率军攻潭州。电子底本也写硃进忠，统一简体姓名，原文保留。生卒年未载。", "biography": null, "status": "draft", "id": "0ba585e1-d1aa-5ce5-ad37-d02d89127713"}, {"name": "许可琼", "aliases": ["許可瓊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "许德勋的儿子，楚国水军指挥使。950年受马希广命率五百艘战舰屯城北津，水军接连南津，由马希崇监军。生卒年未载。", "biography": null, "status": "draft", "id": "31ee592e-a1c4-52e7-8bf7-298a4985dab9"}, {"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "镇州、邢州奏报契丹军围攻内丘，五日未攻克", "start_year": 950, "end_year": 950, "time_original": "950年十一月临朝后收到奏报，围攻发生日未载", "dynasty": "五代十国", "description": "镇州、邢州奏报：契丹君主率数万骑入侵，围攻内丘五日未能攻克，契丹军有死伤。", "phases": [], "location_name": "内丘", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "617c1250-21db-541d-88a5-a580f16e1e68"}, {"title": "内丘五百戍兵倒向契丹，引军入城后城遭屠杀", "start_year": 950, "end_year": 950, "time_original": "950年十一月奏报所述围攻之后，具体陷城日未载", "dynasty": "五代十国", "description": "奏报记内丘五百戍兵倒向契丹，引契丹军入城；城中随后遭到屠杀。", "phases": [], "location_name": "内丘", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9a9e7dba-ec99-5d35-bf32-383ab77cd3a8"}, {"title": "契丹军攻下内丘后又攻陷饶阳", "start_year": 950, "end_year": 950, "time_original": "950年十一月奏报所述，具体陷城日未载", "dynasty": "五代十国", "description": "契丹军攻下内丘后又攻陷饶阳。", "phases": [], "location_name": "饶阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "77b70a13-fe98-56cd-88a3-d063c3daef9b"}, {"title": "李太后命郭威率大军北征契丹", "start_year": 950, "end_year": 950, "time_original": "950年十一月收到契丹入侵奏报后、十二月甲午出发前", "dynasty": "五代十国", "description": "李太后命郭威率大军北征契丹。", "phases": [], "location_name": "后汉朝廷，拟北征", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9162cff1-34bb-59ef-b604-ec7d8c7e2e0a"}, {"title": "郭威北征时，政务暂交窦贞固、苏禹珪和王峻", "start_year": 950, "end_year": 950, "time_original": "950年十一月北征敕命后、十二月甲午出发前", "dynasty": "五代十国", "description": "郭威北征时，政务暂交窦贞固、苏禹珪和王峻。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "12134fad-9be0-5107-9c42-5ee6996ee8ce"}, {"title": "郭威北征时，军事事务交由王殷负责", "start_year": 950, "end_year": 950, "time_original": "950年十一月北征安排时、十二月甲午出发前", "dynasty": "五代十国", "description": "郭威北征时，军事事务交由王殷负责。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "045a5471-80a8-5a98-bf9c-9fa4a2d117a5"}, {"title": "郭威于十二月甲午朔率军离开大梁北征", "start_year": 950, "end_year": 950, "time_original": "950年十二月甲午朔", "dynasty": "五代十国", "description": "郭威于十二月甲午朔率军离开大梁北征。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "13a90ae6-b270-5178-b508-c418594a4a7f"}, {"title": "范质于丁酉被任命为枢密副使", "start_year": 950, "end_year": 950, "time_original": "950年十二月丁酉", "dynasty": "五代十国", "description": "范质于丁酉被任命为枢密副使。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7fc952b7-eb17-5cb3-9c03-ccd1458628ce"}, {"title": "彭士愁派彭师暠交出三州官印，请求归降楚国", "start_year": 940, "end_year": 940, "time_original": "940年正月乙未", "dynasty": "五代十国", "description": "彭士愁派儿子彭师暠率诸酋长，向楚交出溪、锦、奖三州官印，请求归降。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1b955ebb-b889-57a3-a917-219181159efe"}, {"title": "马希广重用彭师暠，任其为强弩指挥使并领辰州刺史", "start_year": null, "end_year": null, "time_original": "马希广在位、950年长沙围城以前，具体任命年日未载", "dynasty": "五代十国", "description": "史书记楚人不喜欢彭师暠的粗直性格，马希广却怜惜他，任他为强弩指挥使，兼领辰州刺史；彭师暠常愿为马希广效死。", "phases": [], "location_name": "楚国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2d088ebb-ab43-5498-b596-cd8db2dbf88f"}, {"title": "朱进忠与部族兵合计七千余人到长沙，驻湘江西岸", "start_year": 950, "end_year": 950, "time_original": "950年长沙围城期间，具体到达日未载", "dynasty": "五代十国", "description": "朱进忠与部族兵合计七千余人到长沙，驻湘江西岸。", "phases": [], "location_name": "长沙湘江西岸", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e2f798a5-9169-5a81-bc43-500718572b31"}, {"title": "彭师暠请求步兵三千，提议与许可琼水军夹攻敌军", "start_year": 950, "end_year": 950, "time_original": "950年长沙围城期间，具体建议日未载", "dynasty": "五代十国", "description": "彭师暠认为朱进忠所部骄纵，建议借步兵三千自巴溪渡江，绕到岳麓后至水西，让许可琼水军渡江配合夹攻。马希广起初打算采纳。", "phases": [], "location_name": "长沙、巴溪、岳麓、水西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ab11ecbe-095d-5497-a78b-827cc9da9161"}, {"title": "马希萼派密使许诺厚利及分治湖南，争取许可琼", "start_year": 950, "end_year": 950, "time_original": "950年长沙围城期间、许可琼阻止进攻方案前", "dynasty": "五代十国", "description": "马希萼派密使许诺厚利及分治湖南，争取许可琼。", "phases": [], "location_name": "长沙围城军中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8d4a1841-325a-5e98-999c-994b48b93302"}, {"title": "许可琼诋毁彭师暠不可信，马希广放弃夹攻方案", "start_year": 950, "end_year": 950, "time_original": "950年长沙围城期间，彭师暠建议进攻后", "dynasty": "五代十国", "description": "许可琼诋毁彭师暠不可信，马希广放弃夹攻方案。", "phases": [], "location_name": "长沙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c5a87be6-4742-565c-ba07-c36890a0a041"}, {"title": "马希萼以四百余艘战舰停泊湘江西岸", "start_year": 950, "end_year": 950, "time_original": "950年长沙围城期间、夹攻方案被放弃后", "dynasty": "五代十国", "description": "马希萼以四百余艘战舰停泊湘江西岸。", "phases": [], "location_name": "长沙湘江西岸", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d69a8346-0845-5550-9623-f9196e085bd5"}, {"title": "马希广令诸将听许可琼指挥，每日赐银五百两", "start_year": 950, "end_year": 950, "time_original": "950年长沙围城期间，具体命令日未载", "dynasty": "五代十国", "description": "马希广令诸将听许可琼指挥，每日赐银五百两。", "phases": [], "location_name": "长沙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6282d7c0-8f23-5d80-9a34-3afd6234f7df"}, {"title": "马希广多次到许可琼营中议事，因其闭营而称赞", "start_year": 950, "end_year": 950, "time_original": "950年长沙围城期间、许可琼掌诸将后", "dynasty": "五代十国", "description": "马希广多次到许可琼营中商议军务。许可琼常闭营，使士卒不知道朗军进退；马希广却称他为真将军，认为无需担忧。", "phases": [], "location_name": "许可琼军营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c92f0dae-98dd-5bf2-954c-dd0e519860e0"}, {"title": "许可琼夜乘小船秘密会马希萼，约定作内应", "start_year": 950, "end_year": 950, "time_original": "950年长沙围城期间，具体秘密会面日未载", "dynasty": "五代十国", "description": "许可琼夜乘小船秘密会马希萼，约定作内应。", "phases": [], "location_name": "水西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "02bd30e2-e399-55cf-a726-eb7a2fcda67c"}, {"title": "彭师暠斥责许可琼，向马希广请求尽快除去他", "start_year": 950, "end_yea