SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "镇州、邢州奏报：契丹君主率数万骑入侵，围攻内丘五日未能攻克，契丹军有死伤。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p069·原文件第74行", "note": "原文：镇州、刑州奏：“契丹主将数万骑入寇，攻内丘，五日不克，死伤其众。；核对说明：刑州沿已有地名邢州规范；数万骑是奏报规模，未给具体人数。奏报时间与实际围攻时间区分。", "status": "draft", "id": "25c02e7f-52c0-5278-82de-fd5575672005", "subject_id": "617c1250-21db-541d-88a5-a580f16e1e68", "source_id": "3162961e-b83b-5558-8393-bf0badc8d5e4"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年十一月临朝后收到奏报，围攻发生日未载", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p069·原文件第74行", "note": "原文：镇州、刑州奏：“契丹主将数万骑入寇，攻内丘，五日不克，死伤其众。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "ea6126a5-362b-5386-a9a5-167fed052d92", "subject_id": "617c1250-21db-541d-88a5-a580f16e1e68", "source_id": "3162961e-b83b-5558-8393-bf0badc8d5e4"}, {"subject_table": "person", "field_path": "description", "claim_text": "耶律阮：率数万骑围攻内丘，五日未克。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p069·原文件第74行", "note": "原文：镇州、刑州奏：“契丹主将数万骑入寇，攻内丘，五日不克，死伤其众。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "b4218f24-5efc-510a-bfb7-5ba2774e9179", "subject_id": "42a17de5-aa28-50e6-bab8-b134f0113f3f", "source_id": "3162961e-b83b-5558-8393-bf0badc8d5e4"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "耶律阮：率数万骑围攻内丘，五日未克。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p069·原文件第74行", "note": "原文：镇州、刑州奏：“契丹主将数万骑入寇，攻内丘，五日不克，死伤其众。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "b3acca8c-a6ea-5d88-81d0-14d08fd7338d", "subject_id": "414d68db-ee47-5d1c-84f2-e2e23a3fe29b", "source_id": "3162961e-b83b-5558-8393-bf0badc8d5e4"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》也记契丹君主率部族入边，围攻内丘五日未下。", "citation": "《旧五代史》卷一百〇三，段落 jiu-wudaishi-205deb4a7860-p002501；EPUB电子本，纸本及异文待核", "note": "原文：鎮州、邢州馳奏，契丹寇洺州，陷內丘縣。時契丹永康王烏裕率部族兩道入邊，內丘城小而固，契丹攻之，五日不下，敵人傷者甚眾。；核对说明：永康王乌裕按既有耶律阮身份识别；《旧五代史》补记两路入边、内丘城小而坚固，不从此推具体入侵日。", "status": "draft", "id": "d0f93272-9bb4-5a9b-ad1f-dd9c6820454c", "subject_id": "617c1250-21db-541d-88a5-a580f16e1e68", "source_id": "50558b51-7a36-5d54-a520-55c401d3f84b"}, {"subject_table": "event", "field_path": "description", "claim_text": "奏报记内丘五百戍兵倒向契丹，引契丹军入城；城中随后遭到屠杀。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p069·原文件第74行", "note": "原文：有戍兵五百叛应契丹，引契丹入城，屠之，；核对说明：被杀人数及具体执行者未载，不凭数百戍兵推全城人口。", "status": "draft", "id": "2589b79d-0fd2-5572-9f9a-156dc3b1e011", "subject_id": "9a9e7dba-ec99-5d35-bf32-383ab77cd3a8", "source_id": "3162961e-b83b-5558-8393-bf0badc8d5e4"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年十一月奏报所述围攻之后，具体陷城日未载", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p069·原文件第74行", "note": "原文：有戍兵五百叛应契丹，引契丹入城，屠之，；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "e09a2328-f792-513a-9c24-6285a1bc4445", "subject_id": "9a9e7dba-ec99-5d35-bf32-383ab77cd3a8", "source_id": "3162961e-b83b-5558-8393-bf0badc8d5e4"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "耶律阮：所率军队因戍兵引入攻下内丘。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p069·原文件第74行", "note": "原文：有戍兵五百叛应契丹，引契丹入城，屠之，；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "7339c236-3165-5d45-af85-6b1364cd3b7d", "subject_id": "92d2808e-ca12-5063-8f45-1b8d8e00bbb6", "source_id": "3162961e-b83b-5558-8393-bf0badc8d5e4"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》也记五百守军在攻势紧迫时投降，契丹军屠城后离去。", "citation": "《旧五代史》卷一百〇三，段落 jiu-wudaishi-205deb4a7860-p002501；EPUB电子本，纸本及异文待核", "note": "原文：時有官軍五百，在城防戍，攻急，官軍降於敵，屠其城而去。；核对说明：投降引入与随后屠城有对应证据，未补死亡总数。", "status": "draft", "id": "0e7e5305-bbce-5407-b96d-539f84584947", "subject_id": "9a9e7dba-ec99-5d35-bf32-383ab77cd3a8", "source_id": "50558b51-7a36-5d54-a520-55c401d3f84b"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "《辽史》将契丹君主攻下内丘等城的南伐记在天禄四年十月。", "citation": "《辽史》卷5·世宗本纪·天禄四年十月南伐，段落 liaoshi-7cd182a20e67-p000611；已核上下文及传主，纸本及异文待核。", "note": "原文：冬十月，自將南伐，攻下安平、內丘、束鹿等城，大獲而還。；核对说明：已核上文四年为天禄四年950年。《通鉴》十一月记录奏报，《辽史》十月叙南伐，不能将奏报月当作围攻月；辽史本条没有守军投降与屠城细节。", "status": "draft", "id": "5353b1f8-eef7-53bd-a128-2243c351e3bb", "subject_id": "9a9e7dba-ec99-5d35-bf32-383ab77cd3a8", "source_id": "744361cb-5128-56a2-9b3f-ca03995dfbf0"}, {"subject_table": "event", "field_path": "description", "claim_text": "契丹军攻下内丘后又攻陷饶阳。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p069·原文件第74行", "note": "原文：又陷饶阳。；核对说明：奏报顺序记又陷，不把辽史的安平、束鹿等名单与饶阳强行互换，也不推饶阳必被屠城。", "status": "draft", "id": "cdb8f0e7-3e4b-5428-93fa-896e9f75389a", "subject_id": "77b70a13-fe98-56cd-88a3-d063c3daef9b", "source_id": "3162961e-b83b-5558-8393-bf0badc8d5e4"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "950年十一月奏报所述，具体陷城日未载", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p069·原文件第74行", "note": "原文：又陷饶阳。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "90d4b20b-c1d5-5b8a-8135-0ff8acbe6b02", "subject_id": "77b70a13-fe98-56cd-88a3-d063c3daef9b", "source_id": "3162961e-b83b-5558-8393-bf0badc8d5e4"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "耶律阮：所率契丹军又攻陷饶阳。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p069·原文件第74行", "note": "原文：又陷饶阳。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "3950c7a1-4056-5785-bf42-2619b429ef86", "subject_id": "a8d613c0-f810-57f2-b293-c46c1737c48a", "source_id": "3162961e-b83b-5558-8393-bf0badc8d5e4"}, {"subject_table": "event", "field_path": "description", "claim_text": "李太后命郭威率大军北征契丹。", "citation": "卷289·乾祐三年（950年十一月至十二月及此前追述）·zztj-v289-y0950-p069·原文件第74行", "note": "原文：太后敕郭威将大军击之，；核对说明：敕命与下一句实际出发分开，不写此时已经交战或击败契丹。", "status": "draft", "id": "a2469945-d07d-5aeb-802e-b272235e4e13", "subject_id": "9162cff1-34bb-59ef-b604-ec